import { translate as t } from '@nextcloud/l10n';
import { showSuccess, showError } from '../../utils/notifications.js';
import { confirmDialog } from '../../utils/dialogs.js';
import { apiFetch } from '../../utils/api.js';
import { refreshBankSyncNav } from './bankSyncStatus.js';
import { importTargetAccounts, accountOptionLabel } from '../../utils/accounts.js';
import { userLocale, formatCurrency } from '../../utils/formatters.js';
import { escapeHtml } from '../../utils/dom.js';

/**
 * Whether a bank authorization link is safe to send the browser to: https
 * only, so a javascript: or data: link from the provider never runs here.
 * The server refuses anything else too; this is the second check.
 * @param {unknown} url
 * @returns {boolean}
 */
export function isHttpsUrl(url) {
    if (typeof url !== 'string' || url === '') return false;
    try {
        return new URL(url).protocol === 'https:';
    } catch (e) {
        return false;
    }
}

/**
 * Open the bank's authorization page in a new window with no link back to
 * this one (noopener) and no referrer. With noopener, window.open always
 * returns null, so a blocked popup can't be told apart from an open one:
 * the "click here" link is always shown and carries the same rel.
 * @param {string} url an https link (see isHttpsUrl)
 */
export function openAuthorizationUrl(url) {
    window.open(url, '_blank', 'noopener,noreferrer');
    const fallback = document.getElementById('bank-sync-auth-link-fallback');
    const link = document.getElementById('bank-sync-auth-link');
    if (link) {
        link.href = url;
        link.rel = 'noopener noreferrer';
    }
    if (fallback) fallback.style.display = 'block';
}

/**
 * Bank Sync Module — manages bank connections, account mappings, and sync operations.
 * Only visible when the admin has enabled bank sync.
 *
 * GoCardless flow: 3-step wizard (credentials → bank selection → authorization).
 * Enable Banking flow: same three steps, but the API keys live server-side, so
 * step 1 only asks for them once (and is skipped when they are stored).
 * SimpleFIN flow: single-step (credentials → connect → done).
 */
export default class BankSyncModule {
    constructor(app) {
        this.app = app;
        this.connections = [];
        this.selectedConnectionId = null;

        // Wizard state
        this._wizardStep = 1;
        this._wizardCredentials = null;
        this._wizardConnectionId = null;
        this._wizardAuthUrl = null;
        this._selectedInstitutionId = null;
        this._institutions = [];
        this._reauthorizeConnectionId = null;
        this._ebSettings = null;
        this._ebReplaceKeys = false;

        // GoCardless supported country codes
        this._countryCodes = [
            'AT', 'BE', 'BG', 'HR', 'CY', 'CZ', 'DK', 'EE', 'FI', 'FR',
            'DE', 'GR', 'HU', 'IS', 'IE', 'IT', 'LV', 'LT', 'LU', 'MT',
            'NL', 'NO', 'PL', 'PT', 'RO', 'SK', 'SI', 'ES', 'SE', 'GB',
        ];
    }

    async init() {
        await this.checkStatus();
        this.setupEventListeners();
    }

    async checkStatus() {
        return refreshBankSyncNav();
    }

    setupEventListeners() {
        if (this._listenersSetup) return;
        this._listenersSetup = true;

        document.addEventListener('click', (e) => {
            if (e.target.closest('#add-bank-connection-btn')) {
                e.preventDefault();
                this.showConnectModal();
            } else if (e.target.closest('#bank-sync-step1-next')) {
                e.preventDefault();
                this.handleStep1Next();
            } else if (e.target.closest('#bank-sync-step2-connect')) {
                e.preventDefault();
                this.handleStep2Connect();
            } else if (e.target.closest('#bank-sync-step2-back')) {
                e.preventDefault();
                this.showWizardStep(1);
            } else if (e.target.closest('#bank-sync-eb-replace-keys')) {
                e.preventDefault();
                this._showEnableBankingKeyInputs();
            } else if (e.target.closest('#bank-sync-eb-copy-callback')) {
                e.preventDefault();
                this._copyEnableBankingCallbackUrl();
            } else if (e.target.closest('#bank-sync-modal .cancel-btn')) {
                // main.js hides the modal; the entered key must not stay in the page
                this._resetWizardState();
            } else if (e.target.closest('#bank-sync-check-auth')) {
                e.preventDefault();
                this.handleCheckAuth();
            } else if (e.target.closest('#sync-all-connections-btn')) {
                e.preventDefault();
                this.syncAll();
            } else if (e.target.closest('#refresh-accounts-btn')) {
                e.preventDefault();
                this.refreshAccounts();
            }
        });

        document.addEventListener('change', (e) => {
            if (e.target.id === 'bank-sync-eb-private-key-file') {
                this._readPrivateKeyFile(e.target.files && e.target.files[0]);
            } else if (e.target.id === 'bank-sync-provider') {
                const provider = e.target.value;
                document.getElementById('simplefin-fields').style.display = provider === 'simplefin' ? 'block' : 'none';
                document.getElementById('gocardless-fields').style.display = provider === 'gocardless' ? 'block' : 'none';
                document.getElementById('enablebanking-fields').style.display = provider === 'enablebanking' ? 'block' : 'none';
                if (provider === 'enablebanking') this.loadEnableBankingSettings();
            } else if (e.target.id === 'bank-sync-country') {
                this.loadInstitutions(e.target.value);
            }
        });

        document.addEventListener('input', (e) => {
            if (e.target.id === 'bank-sync-institution-search') {
                this.filterInstitutions(e.target.value);
            }
        });
    }

    async loadBankSyncView() {
        const status = await this.checkStatus();
        const disabledNotice = document.getElementById('bank-sync-disabled-notice');
        const content = document.getElementById('bank-sync-content');

        if (!status.enabled) {
            if (disabledNotice) disabledNotice.style.display = 'block';
            if (content) content.style.display = 'none';
            return;
        }

        if (disabledNotice) disabledNotice.style.display = 'none';
        if (content) content.style.display = 'block';
        this.setupEventListeners();
        await this.loadConnections();
    }

    // ── Connections ─────────────────────────────────────────────

    async loadConnections() {
        try {
            this.connections = await apiFetch('/apps/budget/api/bank-sync/connections');
            this.renderConnections();
        } catch (error) {
            console.error('Failed to load bank connections:', error);
        }
    }

    renderConnections() {
        const container = document.getElementById('bank-connections-list');
        if (!container) return;

        const syncAllBtn = document.getElementById('sync-all-connections-btn');
        const activeCount = this.connections.filter(c => c.connection.status === 'active').length;
        if (syncAllBtn) {
            syncAllBtn.style.display = activeCount >= 2 ? '' : 'none';
        }

        if (!this.connections.length) {
            container.innerHTML = `<div class="empty-state-small">${t('budget', 'No bank connections yet. Click "Add Connection" to get started.')}</div>`;
            return;
        }

        container.innerHTML = this.connections.map(({ connection, mappings, canReauthorize }) => {
            const statusClass = connection.status === 'active' ? 'positive' : (connection.status === 'error' ? 'negative' : (connection.status === 'pending_auth' ? 'warning' : ''));
            const statusLabel = {
                active: t('budget', 'Active'),
                pending_auth: t('budget', 'Awaiting Authorization'),
                error: t('budget', 'Error'),
                expired: t('budget', 'Expired'),
            }[connection.status] || escapeHtml(connection.status);

            const providerLabel = { gocardless: 'GoCardless', enablebanking: 'Enable Banking' }[connection.provider] || 'SimpleFIN';
            const lastSync = connection.lastSyncAt
                ? t('budget', 'Last sync: {date}', { date: new Date(connection.lastSyncAt).toLocaleString(userLocale()) })
                : t('budget', 'Never synced');
            const mappedCount = mappings.filter(m => m.budgetAccountId && m.enabled).length;
            // The server decides: it alone sees whether a pending Enable
            // Banking authorization failed, timed out or is still under way.
            const actionBtn = canReauthorize
                ? `<button class="btn-warning bank-reauth-btn" data-connection-id="${connection.id}" title="${t('budget', 'Re-authorize')}">${t('budget', 'Re-authorize')}</button>`
                : `<button class="bank-sync-btn" data-connection-id="${connection.id}" title="${t('budget', 'Sync now')}" aria-label="${t('budget', 'Sync now')}">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M17.65,6.35C16.2,4.9 14.21,4 12,4A8,8 0 0,0 4,12A8,8 0 0,0 12,20C15.73,20 18.84,17.45 19.73,14H17.65C16.83,16.33 14.61,18 12,18A6,6 0 0,1 6,12A6,6 0 0,1 12,6C13.66,6 15.14,6.69 16.22,7.78L13,11H20V4L17.65,6.35Z"/></svg>
                </button>
                <button class="bank-force-sync-btn" data-connection-id="${connection.id}" title="${t('budget', 'Re-import previously deleted transactions')}" style="font-size: 11px; padding: 2px 8px; opacity: 0.7;">
                    ${t('budget', 'Force')}
                </button>`;

            return `
                <div class="bank-connection-card" data-connection-id="${connection.id}">
                    <div class="bank-connection-header">
                        <div class="bank-connection-info">
                            <strong>${escapeHtml(connection.name)}</strong>
                            <span class="bank-connection-provider">${providerLabel}</span>
                            <span class="bank-connection-status ${statusClass}">${statusLabel}</span>
                        </div>
                        <div class="bank-connection-actions">
                            ${actionBtn}
                            <button class="bank-mappings-btn" data-connection-id="${connection.id}" title="${t('budget', 'Account mappings')}" aria-label="${t('budget', 'Account mappings')}">
                                <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M3,6H21V8H3V6M3,11H21V13H3V11M3,16H21V18H3V16Z"/></svg>
                            </button>
                            <button class="danger bank-disconnect-btn" data-connection-id="${connection.id}" title="${t('budget', 'Disconnect')}" aria-label="${t('budget', 'Disconnect')}">
                                <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M19,6.41L17.59,5L12,10.59L6.41,5L5,6.41L10.59,12L5,17.59L6.41,19L12,13.41L17.59,19L19,17.59L13.41,12L19,6.41Z"/></svg>
                            </button>
                        </div>
                    </div>
                    <div class="bank-connection-meta">
                        <span>${lastSync}</span>
                        <span>${t('budget', '{count} account(s) mapped', { count: mappedCount })}</span>
                        <label class="bank-connection-toggle" title="${t('budget', 'Auto-apply import rules to synced transactions')}">
                            <input type="checkbox" class="apply-rules-checkbox" data-connection-id="${connection.id}" ${connection.applyRules ? 'checked' : ''}>
                            <span>${t('budget', 'Apply rules')}</span>
                        </label>
                        ${connection.provider === 'simplefin' ? `
                        <label class="bank-connection-toggle" title="${t('budget', 'Also pull pending (not yet posted) transactions. They are marked Pending and reconciled when they post.')}">
                            <input type="checkbox" class="include-pending-checkbox" data-connection-id="${connection.id}" ${connection.includePending ? 'checked' : ''}>
                            <span>${t('budget', 'Include pending')}</span>
                        </label>` : ''}
                        ${connection.lastError ? `<span class="bank-connection-error">${escapeHtml(connection.lastError)}</span>` : ''}
                    </div>
                </div>
            `;
        }).join('');

        container.querySelectorAll('.bank-sync-btn').forEach(btn => {
            btn.addEventListener('click', () => this.syncConnection(parseInt(btn.dataset.connectionId)));
        });
        container.querySelectorAll('.bank-force-sync-btn').forEach(btn => {
            btn.addEventListener('click', () => this.syncConnection(parseInt(btn.dataset.connectionId), true));
        });
        container.querySelectorAll('.bank-reauth-btn').forEach(btn => {
            btn.addEventListener('click', () => this.startReauthorize(parseInt(btn.dataset.connectionId)));
        });
        container.querySelectorAll('.bank-mappings-btn').forEach(btn => {
            btn.addEventListener('click', () => this.showMappings(parseInt(btn.dataset.connectionId)));
        });
        container.querySelectorAll('.apply-rules-checkbox').forEach(cb => {
            cb.addEventListener('change', () => this.updateConnectionApplyRules(parseInt(cb.dataset.connectionId), cb.checked));
        });
        container.querySelectorAll('.include-pending-checkbox').forEach(cb => {
            cb.addEventListener('change', () => this.updateConnectionIncludePending(parseInt(cb.dataset.connectionId), cb.checked));
        });
        container.querySelectorAll('.bank-disconnect-btn').forEach(btn => {
            btn.addEventListener('click', () => this.disconnect(parseInt(btn.dataset.connectionId)));
        });
    }

    // ── Wizard: Modal & Step Navigation ─────────────────────────

    showConnectModal() {
        this._reauthorizeConnectionId = null;
        this._resetWizardState();
        const modal = document.getElementById('bank-sync-modal');
        if (!modal) return;

        document.getElementById('bank-sync-provider').value = '';
        document.getElementById('bank-sync-name').value = '';
        document.getElementById('bank-sync-setup-token').value = '';
        document.getElementById('bank-sync-secret-id').value = '';
        document.getElementById('bank-sync-secret-key').value = '';
        document.getElementById('simplefin-fields').style.display = 'none';
        document.getElementById('gocardless-fields').style.display = 'none';
        document.getElementById('enablebanking-fields').style.display = 'none';
        document.getElementById('bank-sync-provider').disabled = false;
        document.getElementById('bank-sync-name').disabled = false;

        this.showWizardStep(1);
        modal.style.display = 'flex';
    }

    showWizardStep(step) {
        this._wizardStep = step;
        for (let i = 1; i <= 3; i++) {
            const el = document.getElementById(`bank-sync-step-${i}`);
            if (el) el.style.display = i === step ? 'block' : 'none';
        }
        for (let i = 1; i <= 3; i++) {
            const err = document.getElementById(`bank-sync-step${i}-error`);
            if (err) { err.style.display = 'none'; err.textContent = ''; }
        }
        const success = document.getElementById('bank-sync-step3-success');
        if (success) { success.style.display = 'none'; success.textContent = ''; }
    }

    _resetWizardState() {
        this._wizardStep = 1;
        this._wizardCredentials = null;
        this._wizardConnectionId = null;
        this._wizardAuthUrl = null;
        this._selectedInstitutionId = null;
        this._institutions = [];
        this._reauthorizeConnectionId = null;
        this._ebReplaceKeys = false;
        this._authComplete = false;
        this._busy = false;
        const fallback = document.getElementById('bank-sync-auth-link-fallback');
        if (fallback) fallback.style.display = 'none';
        this._setAuthText(false);
        // The private key must not linger in the page after cancel or reopen
        for (const id of ['bank-sync-eb-private-key', 'bank-sync-eb-application-id', 'bank-sync-eb-private-key-file']) {
            const el = document.getElementById(id);
            if (el) el.value = '';
        }
    }

    /** Step 3 wording differs for Enable Banking: the bank's own tab says "Connected". */
    _setAuthText(isEnableBanking) {
        const eb = document.getElementById('bank-sync-auth-text-eb');
        if (eb) eb.style.display = isEnableBanking ? 'block' : 'none';
        document.querySelectorAll('.bank-sync-auth-text-default').forEach(el => {
            el.style.display = isEnableBanking ? 'none' : '';
        });
    }

    _showStepError(step, message) {
        const el = document.getElementById(`bank-sync-step${step}-error`);
        if (el) {
            el.textContent = message;
            el.style.display = 'block';
        }
    }

    // ── Wizard Step 1: Credentials ──────────────────────────────

    async handleStep1Next() {
        if (this._busy) return;

        const provider = document.getElementById('bank-sync-provider').value;
        const name = document.getElementById('bank-sync-name').value.trim();

        if (!provider) {
            this._showStepError(1, t('budget', 'Please select a provider'));
            return;
        }
        if (!name) {
            this._showStepError(1, t('budget', 'Please enter a connection name'));
            return;
        }

        if (provider === 'simplefin') {
            await this._connectSimpleFIN(name);
            return;
        }

        if (provider === 'enablebanking') {
            await this._connectEnableBankingStep1(name);
            return;
        }

        const secretId = document.getElementById('bank-sync-secret-id').value.trim();
        const secretKey = document.getElementById('bank-sync-secret-key').value.trim();

        if (!secretId || !secretKey) {
            this._showStepError(1, t('budget', 'Please enter your API credentials'));
            return;
        }

        this._wizardCredentials = { secretId, secretKey, name, provider };

        const btn = document.getElementById('bank-sync-step1-next');
        this._busy = true;
        btn.disabled = true;
        btn.textContent = t('budget', 'Validating...');

        try {
            this._populateCountryDropdown();
            const country = document.getElementById('bank-sync-country').value;
            await this.loadInstitutions(country);
            this.showWizardStep(2);
        } catch (error) {
            this._showStepError(1, t('budget', 'Invalid credentials: {error}', { error: error.message }));
        } finally {
            this._busy = false;
            btn.disabled = false;
            btn.textContent = t('budget', 'Next');
        }
    }

    // ── Enable Banking: keys & step 1 ───────────────────────────

    /**
     * Fetches the stored-keys state (never the key itself) and shows either the
     * "keys stored" notice or the key inputs. Also fills the redirect URL the
     * user has to register with Enable Banking.
     */
    async loadEnableBankingSettings() {
        try {
            this._ebSettings = await apiFetch('/apps/budget/api/bank-sync/enablebanking/settings');
        } catch (error) {
            this._showStepError(1, t('budget', 'Failed to load Enable Banking settings: {error}', { error: error.message }));
            return null;
        }

        this._ebReplaceKeys = false;
        const callback = document.getElementById('bank-sync-eb-callback-url');
        if (callback) callback.value = this._ebSettings.callbackUrl || '';
        this._toggleEnableBankingKeyInputs(!this._ebSettings.hasKeys);
        return this._ebSettings;
    }

    _toggleEnableBankingKeyInputs(showInputs) {
        const stored = document.getElementById('bank-sync-eb-keys-stored');
        const inputs = document.getElementById('bank-sync-eb-key-inputs');
        if (stored) stored.style.display = showInputs ? 'none' : 'block';
        if (inputs) inputs.style.display = showInputs ? 'block' : 'none';
    }

    _showEnableBankingKeyInputs() {
        this._ebReplaceKeys = true;
        const appId = document.getElementById('bank-sync-eb-application-id');
        if (appId && !appId.value && this._ebSettings?.applicationId) appId.value = this._ebSettings.applicationId;
        this._toggleEnableBankingKeyInputs(true);
    }

    /** Reads the PEM client-side so the file itself never leaves the browser except as the PUT body. */
    _readPrivateKeyFile(file) {
        if (!file) return;
        const reader = new FileReader();
        reader.onload = () => {
            document.getElementById('bank-sync-eb-private-key').value = String(reader.result || '');
        };
        reader.onerror = () => {
            this._showStepError(1, t('budget', 'Could not read the key file'));
        };
        reader.readAsText(file);
    }

    async _copyEnableBankingCallbackUrl() {
        const input = document.getElementById('bank-sync-eb-callback-url');
        if (!input || !input.value) return;
        try {
            await navigator.clipboard.writeText(input.value);
            showSuccess(t('budget', 'Copied'));
        } catch (error) {
            input.select();
        }
    }

    async _connectEnableBankingStep1(name) {
        this._wizardCredentials = { name, provider: 'enablebanking' };

        const btn = document.getElementById('bank-sync-step1-next');
        this._busy = true;
        btn.disabled = true;
        btn.textContent = t('budget', 'Validating...');

        try {
            if (!this._ebSettings) await this.loadEnableBankingSettings();

            if (!this._ebSettings?.hasKeys || this._ebReplaceKeys) {
                const applicationId = document.getElementById('bank-sync-eb-application-id').value.trim();
                const privateKey = document.getElementById('bank-sync-eb-private-key').value.trim();
                if (!applicationId || !privateKey) {
                    this._showStepError(1, t('budget', 'Please enter your application ID and private key'));
                    return;
                }
                await apiFetch('/apps/budget/api/bank-sync/enablebanking/settings', {
                    method: 'PUT',
                    body: { applicationId, privateKey },
                });
                this._ebSettings = { ...this._ebSettings, hasKeys: true, applicationId };
                this._ebReplaceKeys = false;
                this._toggleEnableBankingKeyInputs(false);
                document.getElementById('bank-sync-eb-private-key').value = '';
            }

            await this._showEnableBankingBanks();
        } catch (error) {
            this._showStepError(1, t('budget', 'Failed to connect: {error}', { error: error.message }));
        } finally {
            this._busy = false;
            btn.disabled = false;
            btn.textContent = t('budget', 'Next');
        }
    }

    async _showEnableBankingBanks() {
        this._populateCountryDropdown();
        // Germany is the main market; the user can switch country on step 2.
        document.getElementById('bank-sync-country').value = 'DE';
        await this.loadInstitutions('DE');
        this.showWizardStep(2);
    }

    async _connectSimpleFIN(name) {
        const setupToken = document.getElementById('bank-sync-setup-token').value.trim();
        if (!setupToken) {
            this._showStepError(1, t('budget', 'Please enter a setup token'));
            return;
        }

        const btn = document.getElementById('bank-sync-step1-next');
        this._busy = true;
        btn.disabled = true;
        btn.textContent = t('budget', 'Connecting...');

        try {
            await apiFetch('/apps/budget/api/bank-sync/connections', {
                method: 'POST',
                body: { provider: 'simplefin', name, setupToken },
            });

            document.getElementById('bank-sync-modal').style.display = 'none';
            showSuccess(t('budget', 'Bank connected successfully'));
            await this.loadConnections();
        } catch (error) {
            this._showStepError(1, t('budget', 'Failed to connect: {error}', { error: error.message }));
        } finally {
            this._busy = false;
            btn.disabled = false;
            btn.textContent = t('budget', 'Next');
        }
    }

    // ── Wizard Step 2: Institution Selection ────────────────────

    _populateCountryDropdown() {
        const select = document.getElementById('bank-sync-country');
        if (!select || select.options.length > 1) return;

        select.innerHTML = '';
        const lang = OC.getLanguage ? OC.getLanguage() : 'en';
        const localeParts = lang.split(/[-_]/);
        const detectedCountry = (localeParts[1] || 'gb').toUpperCase();

        let displayNames;
        try {
            displayNames = new Intl.DisplayNames([lang], { type: 'region' });
        } catch (e) {
            displayNames = new Intl.DisplayNames(['en'], { type: 'region' });
        }

        const countries = this._countryCodes
            .map(code => ({ code, name: displayNames.of(code) || code }))
            .sort((a, b) => a.name.localeCompare(b.name));

        countries.forEach(c => {
            const opt = document.createElement('option');
            opt.value = c.code;
            opt.textContent = c.name;
            if (c.code === detectedCountry) opt.selected = true;
            select.appendChild(opt);
        });

        if (!select.value) {
            select.value = 'GB';
        }
    }

    async loadInstitutions(country) {
        const grid = document.getElementById('bank-sync-institutions-grid');
        const loading = document.getElementById('bank-sync-institutions-loading');
        const searchInput = document.getElementById('bank-sync-institution-search');

        if (loading) loading.style.display = 'block';
        if (grid) grid.innerHTML = '';
        if (searchInput) searchInput.value = '';
        this._selectedInstitutionId = null;
        this._updateConnectButton();

        const creds = this._wizardCredentials || {};
        const provider = creds.provider || 'gocardless';
        // Enable Banking keys are held server-side, so only GoCardless sends secrets.
        const body = provider === 'gocardless'
            ? { country, secretId: creds.secretId || '', secretKey: creds.secretKey || '' }
            : { country };

        try {
            this._institutions = await apiFetch(`/apps/budget/api/bank-sync/providers/${provider}/institutions`, {
                method: 'POST',
                body,
            });
            this.renderInstitutions(this._institutions);
        } catch (error) {
            this._showStepError(2, t('budget', 'Failed to load banks: {error}', { error: error.message }));
            throw error;
        } finally {
            if (loading) loading.style.display = 'none';
        }
    }

    renderInstitutions(institutions) {
        const grid = document.getElementById('bank-sync-institutions-grid');
        if (!grid) return;

        if (!institutions.length) {
            grid.innerHTML = `<div class="empty-state-small">${t('budget', 'No banks found for this country.')}</div>`;
            return;
        }

        // Nextcloud's CSP blocks Enable Banking's logo hosts, so show names only.
        const showLogos = this._wizardCredentials?.provider !== 'enablebanking';

        grid.innerHTML = institutions.map(inst => `
            <div class="bank-institution-tile" data-institution-id="${escapeHtml(inst.id)}" tabindex="0" role="button">
                ${!showLogos ? '' : inst.logo ? `<img src="${escapeHtml(inst.logo)}" alt="" class="bank-institution-logo" loading="lazy">` : '<div class="bank-institution-logo-placeholder"></div>'}
                <span class="bank-institution-name">${escapeHtml(inst.name)}</span>
            </div>
        `).join('');

        grid.querySelectorAll('.bank-institution-tile').forEach(tile => {
            tile.addEventListener('click', () => this._selectInstitution(tile));
            tile.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    this._selectInstitution(tile);
                }
            });
        });
    }

    _selectInstitution(tile) {
        const grid = document.getElementById('bank-sync-institutions-grid');
        grid.querySelectorAll('.bank-institution-tile.selected').forEach(t => t.classList.remove('selected'));
        tile.classList.add('selected');
        this._selectedInstitutionId = tile.dataset.institutionId;
        this._updateConnectButton();
    }

    _updateConnectButton() {
        const btn = document.getElementById('bank-sync-step2-connect');
        if (btn) btn.disabled = !this._selectedInstitutionId;
    }

    filterInstitutions(query) {
        const lower = query.toLowerCase();
        const filtered = lower
            ? this._institutions.filter(inst => inst.name.toLowerCase().includes(lower))
            : this._institutions;
        this.renderInstitutions(filtered);
    }

    // ── Wizard Step 2 → 3: Connect & Open Auth ──────────────────

    async handleStep2Connect() {
        if (!this._selectedInstitutionId || this._busy) return;

        const btn = document.getElementById('bank-sync-step2-connect');
        this._busy = true;
        btn.disabled = true;
        btn.textContent = t('budget', 'Connecting...');

        const redirectUrl = window.location.href.split('#')[0];
        const isEnableBanking = this._wizardCredentials?.provider === 'enablebanking';

        // Enable Banking needs the country and the bank's consent limit, and the
        // server sets the redirect URL itself (it points at the callback page).
        let ebFields = {};
        if (isEnableBanking) {
            const inst = this._institutions.find(i => i.id === this._selectedInstitutionId);
            ebFields = {
                country: document.getElementById('bank-sync-country').value,
                maximumConsentValidity: inst?.maximumConsentValidity,
            };
        }

        try {
            let result;

            if (this._reauthorizeConnectionId) {
                result = await apiFetch(`/apps/budget/api/bank-sync/connections/${this._reauthorizeConnectionId}/reauthorize`, {
                    method: 'POST',
                    body: isEnableBanking
                        ? { institutionId: this._selectedInstitutionId, ...ebFields }
                        : { institutionId: this._selectedInstitutionId, redirectUrl },
                });
                this._wizardConnectionId = this._reauthorizeConnectionId;
            } else {
                const creds = this._wizardCredentials;
                result = await apiFetch('/apps/budget/api/bank-sync/connections', {
                    method: 'POST',
                    body: isEnableBanking
                        ? {
                            provider: 'enablebanking',
                            name: creds.name,
                            institutionId: this._selectedInstitutionId,
                            ...ebFields,
                        }
                        : {
                            provider: 'gocardless',
                            name: creds.name,
                            secretId: creds.secretId,
                            secretKey: creds.secretKey,
                            institutionId: this._selectedInstitutionId,
                            redirectUrl,
                        },
                });
                this._wizardConnectionId = result.connection?.id;
            }

            this._setAuthText(isEnableBanking);
            this._wizardAuthUrl = isHttpsUrl(result.authorizationUrl) ? result.authorizationUrl : null;
            if (this._wizardAuthUrl) {
                openAuthorizationUrl(this._wizardAuthUrl);
            }

            this.showWizardStep(3);
        } catch (error) {
            this._showStepError(2, t('budget', 'Failed to connect: {error}', { error: error.message }));
        } finally {
            this._busy = false;
            btn.disabled = false;
            btn.textContent = t('budget', 'Connect');
        }
    }

    // ── Wizard Step 3: Check Authorization ──────────────────────

    async handleCheckAuth() {
        if (!this._wizardConnectionId) return;

        // If auth already completed, close and reload
        if (this._authComplete) {
            document.getElementById('bank-sync-modal').style.display = 'none';
            this.loadConnections();
            return;
        }

        if (this._busy) return;

        const btn = document.getElementById('bank-sync-check-auth');
        this._busy = true;
        btn.disabled = true;
        btn.textContent = t('budget', 'Checking...');

        try {
            const mappings = await apiFetch(`/apps/budget/api/bank-sync/connections/${this._wizardConnectionId}/refresh`, {
                method: 'POST',
            });

            if (Array.isArray(mappings) && mappings.length > 0) {
                this._authComplete = true;
                const successEl = document.getElementById('bank-sync-step3-success');
                if (successEl) {
                    successEl.textContent = t('budget', 'Authorization successful! {count} account(s) found. You can now close this dialog and set up your account mappings.', { count: mappings.length });
                    successEl.style.display = 'block';
                }
                btn.textContent = t('budget', 'Done');
                btn.disabled = false;
            } else {
                this._showStepError(3, t('budget', 'Authorization not yet complete. Please finish the authorization in the bank window and try again.'));
            }
        } catch (error) {
            this._showStepError(3, t('budget', 'Authorization check failed: {error}', { error: error.message }));
        } finally {
            this._busy = false;
            if (!this._authComplete) {
                btn.disabled = false;
                btn.textContent = t('budget', "I've Completed Authorization");
            }
        }
    }

    // ── Re-Authorization ────────────────────────────────────────

    async startReauthorize(connectionId) {
        const conn = this.connections.find(c => c.connection.id === connectionId);
        if (!conn) return;

        this._resetWizardState();
        this._reauthorizeConnectionId = connectionId;

        const modal = document.getElementById('bank-sync-modal');
        if (!modal) return;

        if (conn.connection.provider === 'enablebanking') {
            await this._startEnableBankingReauthorize(conn, modal);
            return;
        }

        document.getElementById('bank-sync-provider').value = 'gocardless';
        document.getElementById('bank-sync-provider').disabled = true;
        document.getElementById('bank-sync-name').value = conn.connection.name;
        document.getElementById('bank-sync-name').disabled = true;
        document.getElementById('gocardless-fields').style.display = 'block';
        document.getElementById('simplefin-fields').style.display = 'none';
        document.getElementById('enablebanking-fields').style.display = 'none';
        document.getElementById('bank-sync-secret-id').value = '';
        document.getElementById('bank-sync-secret-key').value = '';

        this.showWizardStep(1);
        modal.style.display = 'flex';
    }

    /** Keys are stored server-side, so re-authorizing goes straight to the bank list unless they are missing. */
    async _startEnableBankingReauthorize(conn, modal) {
        document.getElementById('bank-sync-provider').value = 'enablebanking';
        document.getElementById('bank-sync-provider').disabled = true;
        document.getElementById('bank-sync-name').value = conn.connection.name;
        document.getElementById('bank-sync-name').disabled = true;
        document.getElementById('gocardless-fields').style.display = 'none';
        document.getElementById('simplefin-fields').style.display = 'none';
        document.getElementById('enablebanking-fields').style.display = 'block';
        document.getElementById('bank-sync-eb-application-id').value = '';
        document.getElementById('bank-sync-eb-private-key').value = '';
        this._wizardCredentials = { name: conn.connection.name, provider: 'enablebanking' };

        this.showWizardStep(1);
        modal.style.display = 'flex';

        const settings = await this.loadEnableBankingSettings();
        if (!settings?.hasKeys) return;

        try {
            await this._showEnableBankingBanks();
        } catch (error) {
            // loadInstitutions already printed the reason on step 2; show it where the user is
            this._showStepError(1, t('budget', 'Failed to load banks: {error}', { error: error.message }));
        }
    }

    // ── Sync ────────────────────────────────────────────────────

    async syncConnection(connectionId, force = false) {
        try {
            showSuccess(t('budget', force ? 'Force syncing...' : 'Syncing...'));
            const result = await apiFetch(`/apps/budget/api/bank-sync/connections/${connectionId}/sync`, {
                method: 'POST',
                body: { force },
            });

            if (result.message) {
                showError(result.message);
                this.showMappings(connectionId);
            } else {
                showSuccess(t('budget', 'Sync complete: {imported} imported, {skipped} skipped', {
                    imported: result.imported,
                    skipped: result.skipped
                }));
            }

            await this.loadConnections();
        } catch (error) {
            console.error('Failed to sync:', error);
            showError(t('budget', 'Sync failed: {error}', { error: error.message }));
            await this.loadConnections();
        }
    }

    // ── Sync All ────────────────────────────────────────────────

    async syncAll() {
        const activeConnections = this.connections.filter(c => c.connection.status === 'active');
        if (!activeConnections.length) return;

        const btn = document.getElementById('sync-all-connections-btn');
        if (btn) btn.disabled = true;

        let totalImported = 0;
        let totalSkipped = 0;
        let synced = 0;
        let errors = 0;

        for (let i = 0; i < activeConnections.length; i++) {
            const conn = activeConnections[i].connection;
            showSuccess(t('budget', 'Syncing {current} of {total}...', { current: i + 1, total: activeConnections.length }));

            try {
                const result = await apiFetch(`/apps/budget/api/bank-sync/connections/${conn.id}/sync`, {
                    method: 'POST',
                });
                totalImported += result.imported || 0;
                totalSkipped += result.skipped || 0;
                synced++;
            } catch (error) {
                console.error(`Failed to sync connection ${conn.id}:`, error);
                errors++;
            }
        }

        if (errors > 0) {
            showError(t('budget', 'Synced {synced} of {total} connections: {imported} imported, {skipped} skipped, {errors} failed', {
                synced, total: activeConnections.length, imported: totalImported, skipped: totalSkipped, errors
            }));
        } else {
            showSuccess(t('budget', 'Synced {synced} connections: {imported} imported, {skipped} skipped', {
                synced, imported: totalImported, skipped: totalSkipped
            }));
        }

        if (btn) btn.disabled = false;
        await this.loadConnections();
    }

    // ── Disconnect ──────────────────────────────────────────────

    async disconnect(connectionId) {
        if (!await confirmDialog(t('budget', 'Are you sure you want to disconnect this bank? This will remove the connection and all account mappings.'), { destructive: true })) {
            return;
        }

        try {
            await apiFetch(`/apps/budget/api/bank-sync/connections/${connectionId}`, {
                method: 'DELETE',
            });

            showSuccess(t('budget', 'Bank disconnected'));
            const mappingsSection = document.getElementById('bank-mappings-section');
            if (mappingsSection) mappingsSection.style.display = 'none';
            await this.loadConnections();
        } catch (error) {
            showError(t('budget', 'Failed to disconnect bank'));
        }
    }

    // ── Account Mappings ────────────────────────────────────────

    async showMappings(connectionId) {
        this.selectedConnectionId = connectionId;
        const section = document.getElementById('bank-mappings-section');
        if (!section) return;

        try {
            const mappings = await apiFetch(`/apps/budget/api/bank-sync/connections/${connectionId}/mappings`);
            section.style.display = 'block';

            const conn = this.connections.find(c => c.connection.id === connectionId);
            const title = document.getElementById('bank-mappings-title');
            if (title && conn) {
                title.textContent = t('budget', 'Account Mappings — {name}', { name: conn.connection.name });
            }

            this.renderMappings(mappings, connectionId);
        } catch (error) {
            showError(t('budget', 'Failed to load account mappings'));
        }
    }

    renderMappings(mappings, connectionId) {
        const container = document.getElementById('bank-mappings-list');
        if (!container) return;

        // A mapping syncs NEW transactions in, so closed accounts are not offered
        // — except one a mapping already targets (#372). Nor are accounts
        // shared with you: the sync imports as you, not as their owner.
        const accounts = importTargetAccounts(this.app.accounts, mappings.map(m => m.budgetAccountId));
        const accountOptions = accounts.map(a =>
            `<option value="${escapeHtml(a.id)}">${escapeHtml(accountOptionLabel(a))} (${escapeHtml(a.currency)})</option>`
        ).join('');

        container.innerHTML = mappings.map(mapping => {
            const enabled = mapping.enabled ? 'checked' : '';
            // Both come from the bank provider: text, never markup
            const balance = mapping.lastBalance
                ? `${escapeHtml(mapping.lastCurrency || '')} ${escapeHtml(mapping.lastBalance)}`
                : '';
            const balanceCheck = this.renderBalanceCheck(mapping);

            return `
                <div class="bank-mapping-row" data-mapping-id="${mapping.id}">
                    <div class="bank-mapping-info">
                        <label class="bank-mapping-enable">
                            <input type="checkbox" class="mapping-enabled-checkbox"
                                   data-mapping-id="${mapping.id}" data-connection-id="${connectionId}" ${enabled}>
                        </label>
                        <div>
                            <strong>${escapeHtml(mapping.externalAccountName || mapping.externalAccountId)}</strong>
                            ${balance ? `<small>${balance}</small>` : ''}
                            ${mapping.consentExpires ? `<small class="consent-warning">${t('budget', 'Consent expires: {date}', { date: new Date(mapping.consentExpires).toLocaleDateString(userLocale()) })}</small>` : ''}
                            ${balanceCheck}
                        </div>
                    </div>
                    <div class="bank-mapping-target">
                        <select class="mapping-account-select" data-mapping-id="${mapping.id}" data-connection-id="${connectionId}" aria-label="${t('budget', 'Budget account for {account}', { account: mapping.externalAccountName || mapping.externalAccountId })}">
                            <option value="">${t('budget', '— Not mapped —')}</option>
                            ${accountOptions}
                        </select>
                    </div>
                </div>
            `;
        }).join('');

        mappings.forEach(mapping => {
            if (mapping.budgetAccountId) {
                const select = container.querySelector(`.mapping-account-select[data-mapping-id="${mapping.id}"]`);
                if (select) select.value = mapping.budgetAccountId;
            }
        });

        container.querySelectorAll('.mapping-enabled-checkbox').forEach(cb => {
            cb.addEventListener('change', () => this.updateMapping(
                parseInt(cb.dataset.connectionId),
                parseInt(cb.dataset.mappingId),
                null,
                cb.checked
            ));
        });

        container.querySelectorAll('.bank-reconcile-btn').forEach(btn => {
            btn.addEventListener('click', () => this.reconcileMapping(
                mappings,
                connectionId,
                parseInt(btn.dataset.mappingId)
            ));
        });

        container.querySelectorAll('.mapping-account-select').forEach(sel => {
            sel.addEventListener('change', () => this.updateMapping(
                parseInt(sel.dataset.connectionId),
                parseInt(sel.dataset.mappingId),
                sel.value ? parseInt(sel.value) : null,
                null
            ));
        });
    }

    /**
     * The bank's balance against Budget's, shown only when they differ. The
     * gap usually means a missing or doubled transaction, so it is never
     * corrected on its own: Reconcile is the user's call.
     */
    renderBalanceCheck(mapping) {
        const difference = mapping.balanceDifference;
        if (difference === null || difference === undefined || Number(difference) === 0) return '';

        const settings = this.app.settings || {};
        const currency = mapping.lastCurrency;
        const bank = Number(mapping.lastBalance);
        const text = t('budget', 'Bank: {bank} · Budget: {budget} · Difference: {difference}', {
            bank: formatCurrency(bank, currency, settings),
            budget: formatCurrency(bank - Number(difference), currency, settings),
            difference: formatCurrency(Number(difference), currency, settings),
        });

        return `<small class="bank-balance-check consent-warning">${text}</small>
            <button class="bank-reconcile-btn" data-mapping-id="${mapping.id}" title="${t('budget', 'Set the opening balance so that the balance matches the bank')}">${t('budget', 'Reconcile')}</button>`;
    }

    async reconcileMapping(mappings, connectionId, mappingId) {
        try {
            const result = await apiFetch(`/apps/budget/api/bank-sync/connections/${connectionId}/mappings/${mappingId}/reconcile`, {
                method: 'POST',
            });
            const mapping = mappings.find(m => m.id === mappingId);
            if (mapping) mapping.balanceDifference = result.balanceDifference;
            this.renderMappings(mappings, connectionId);
            showSuccess(t('budget', 'Balance matched to the bank'));
        } catch (error) {
            showError(t('budget', 'Failed to reconcile the balance'));
        }
    }

    async updateMapping(connectionId, mappingId, budgetAccountId, enabled) {
        try {
            const body = {};
            if (budgetAccountId !== null) body.budgetAccountId = budgetAccountId;
            if (enabled !== null) body.enabled = enabled;

            await apiFetch(`/apps/budget/api/bank-sync/connections/${connectionId}/mappings/${mappingId}`, {
                method: 'PUT',
                body,
            });

            showSuccess(t('budget', 'Mapping updated'));
        } catch (error) {
            showError(t('budget', 'Failed to update mapping'));
        }
    }

    // ── Refresh Accounts ────────────────────────────────────────

    async refreshAccounts() {
        if (!this.selectedConnectionId) return;

        const btn = document.getElementById('refresh-accounts-btn');
        if (btn) btn.disabled = true;

        try {
            const mappings = await apiFetch(`/apps/budget/api/bank-sync/connections/${this.selectedConnectionId}/refresh`, {
                method: 'POST',
            });
            this.renderMappings(mappings, this.selectedConnectionId);
            showSuccess(t('budget', 'Accounts refreshed'));
        } catch (error) {
            showError(t('budget', 'Failed to refresh accounts: {error}', { error: error.message }));
        } finally {
            if (btn) btn.disabled = false;
        }
    }

    // ── Utilities ───────────────────────────────────────────────

    async updateConnectionApplyRules(connectionId, applyRules) {
        try {
            await apiFetch(`/apps/budget/api/bank-sync/connections/${connectionId}`, {
                method: 'PUT',
                body: { applyRules },
            });
            showSuccess(t('budget', applyRules ? 'Import rules will be applied during sync' : 'Import rules disabled for this connection'));
        } catch (error) {
            showError(t('budget', 'Failed to update connection settings'));
        }
    }

    async updateConnectionIncludePending(connectionId, includePending) {
        try {
            await apiFetch(`/apps/budget/api/bank-sync/connections/${connectionId}`, {
                method: 'PUT',
                body: { includePending },
            });
            showSuccess(t('budget', includePending ? 'Pending transactions will be included during sync' : 'Pending transactions excluded for this connection'));
        } catch (error) {
            showError(t('budget', 'Failed to update connection settings'));
        }
    }

}
